        float angle = body.getAngle() * MathUtils.radiansToDegrees;
        float xOffset =
                (body.getPosition().x - mVehicle.getPosition().x) / Constants.UNIT_FOR_PIXEL;
        float yOffset =
                (body.getPosition().y - mVehicle.getPosition().y) / Constants.UNIT_FOR_PIXEL;
